wallpapers.glsl:
// Ocean: nth's own. Deep water seen from below the surface: light falls in shafts from a rippling surface, caustics dance over a sandy floor,
// particles drift, and a shark glides across the window once a loop, a dark silhouette with a swaying tail that the glass bends as it passes.
// Palette: 0 the deep, 1 the shallows, 2 the surface light, 3 the sand, 4 the shark, 5 the shafts.
// Options: x = motion (waves and caustics), y = shark (0 none, 1 close and large).
const float T = 40.0;

float caustic(vec2 q, float a) {
  float c = 0.0;
  for (int i = 0; i < 3; i++) {
    float f = float(i);
    vec2 r = q * (2.2 + f * 1.3) + vec2(cos(a + f * 2.1), sin(a * 1.0 + f)) * 0.6;
    c += abs(sin(r.x + sin(r.y * 1.3 + a)) * sin(r.y + sin(r.x * 1.1 - a)));
  }
  return pow(sat(1.0 - c / 1.6), 3.0);
}

float sharkShape(vec2 q, float a) {
  // body: a tapered ellipse along +x, the head at x > 0
  float len = 0.62;
  float x = q.x / len;
  float sway = 0.06 * sin(a * 6.0 - q.x * 7.0) * smoothstep(0.1, -0.9, x);
  float y = q.y - sway;
  float half_ = 0.11 * sqrt(sat(1.0 - x * x)) * (x > 0.0 ? 1.0 - 0.35 * x * x : 1.0 - 0.75 * x * x);
  float body = smoothstep(u_px * 2.0, -u_px * 2.0, abs(y) - half_) * step(-1.0, x) * step(x, 1.0);
  // dorsal fin, pectoral fin and the tail fork
  vec2 d = vec2(q.x + 0.02, y - 0.09);
  float dorsal = step(0.0, d.y) * step(d.y, 0.13) * step(abs(d.x - d.y * 0.6), 0.07 * (1.0 - d.y / 0.13));
  vec2 pc = vec2(q.x - 0.1, y + 0.08);
  float pect = step(pc.y, 0.0) * step(-0.11, pc.y) * step(abs(pc.x + pc.y * 0.9), 0.05 * (1.0 + pc.y / 0.11));
  vec2 tq = vec2(q.x + len + 0.02, y);
  float tail = step(-0.15, tq.x) * step(tq.x, 0.0) * step(abs(abs(tq.y) - (-tq.x) * 0.9), 0.035);
  return sat(max(max(body, dorsal), max(pect, tail)));
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float m = mix(0.3, 1.5, u_opt.x);
  float sharkAmt = u_opt.y;
  float depth = sat(0.5 - 0.5 * p.y);
  vec3 col = mix(u_pal[1], u_pal[0], smoothstep(-0.2, 1.0, depth));
  // the surface: a bright rippling band at the top
  float surf = smoothstep(0.55, 1.05, p.y + 0.04 * sin(p.x * 6.0 + a * 2.0) * m + 0.02 * lnoise(vec2(p.x * 2.0, 1.0), a, 0.5));
  col = mix(col, u_pal[2], surf * 0.7);
  // light shafts from the surface, swaying
  vec2 tp = p + tiltD(0.6);
  float shafts = 0.0;
  for (int i = 0; i < 4; i++) {
    float f = float(i);
    float x0 = -1.3 + f * 0.85 + 0.15 * sin(a + f * 1.7) * m;
    float w = 0.08 + 0.05 * sin(f * 2.3 + a * 2.0);
    float s = gauss(tp.x - x0 - (1.0 - tp.y) * 0.25, w) * smoothstep(-1.0, 0.9, tp.y);
    shafts += s * (0.5 + 0.5 * sin(a * 3.0 + f));
  }
  col = mix(col, u_pal[5], sat(shafts * 0.35));
  // the sandy floor with caustics
  float floorY = -0.72 + 0.04 * sin(p.x * 3.0 + 1.0);
  float onFloor = smoothstep(floorY + 0.04, floorY - 0.04, p.y);
  vec3 sand = u_pal[3];
  sand.x += 0.12 * m * caustic(vec2(p.x, p.y * 2.5) + tiltD(-0.8), a);
  col = mix(col, sand, onFloor);
  col.x += 0.06 * m * caustic(p * 0.8, a) * (1.0 - depth) * (1.0 - onFloor);
  // drifting particles
  vec2 g = p * 9.0 + vec2(0.0, 18.0 * t / T); // 18 whole cells a loop, and the cells repeat every 18, so the motes join up
  vec2 id = floor(g); id.y = mod(id.y, 18.0);
  vec3 h = hash33(vec3(id, 5.0)) * 0.5 + 0.5;
  float dot_ = smoothstep(0.08, 0.0, length(fract(g) - h.xy)) * step(0.8, h.z);
  col.x += dot_ * 0.08;
  // the shark: crosses once a loop, its depth by the option
  if (sharkAmt > 0.01) {
    float scale = mix(0.55, 1.35, sharkAmt);
    float phase = fract(t / T);
    vec2 c = vec2(mix(-2.6, 2.6, phase), -0.05 + 0.12 * sin(a));
    vec2 q = (p - c - tiltD(1.2)) / scale;
    float s = sharkShape(q, a);
    vec3 sk = u_pal[4];
    sk.x += 0.08 * smoothstep(0.0, -0.08, q.y); // a paler belly
    float haze = mix(0.55, 0.0, sharkAmt);
    col = mix(col, mix(sk, col, haze), s);
  }
  return outLab(col);
}

// Gradient Plane: nth's own, its parameters inspired by ruucm/shadergradient (no licence, so its ideas only: a lit plane deformed by flowing
// noise, coloured by three colours, with grain). Palette: 0 to 2 the three colours, 3 the shadow, 4 the light, 5 the grain tint.
// Options: x = strength (how far the noise moves the surface), y = density (its frequency).
const float T = 36.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float strength = mix(0.15, 1.6, u_opt.x);
  float density = mix(0.6, 3.2, u_opt.y);
  vec2 q = p + tiltD(0.8);
  vec2 uv = q * 0.9;
  float shade = 1.0;
  float mask = 1.0;
  float h = fbm3(vec3(uv * density, 0.0) + vec3(cos(a), sin(a), 0.0) * 0.6) * strength;
  float g = sat(0.5 + 0.5 * (uv.y * 0.6 + h));
  vec3 c = mix(u_pal[0], u_pal[1], smoothstep(0.0, 0.55, g));
  c = mix(c, u_pal[2], smoothstep(0.45, 1.0, g));
  float e = 0.02;
  float hx = fbm3(vec3((uv + vec2(e, 0.0)) * density, 0.0) + vec3(cos(a), sin(a), 0.0) * 0.6) * strength - h;
  float hy = fbm3(vec3((uv + vec2(0.0, e)) * density, 0.0) + vec3(cos(a), sin(a), 0.0) * 0.6) * strength - h;
  vec3 nrm = normalize(vec3(-hx / e * 0.15, -hy / e * 0.15, 1.0));
  float lit = sat(dot(nrm, normalize(vec3(-0.4, 0.6, 0.7))));
  c.x += (lit - 0.6) * 0.18 * shade;
  c = mix(c, u_pal[4], pow(lit, 24.0) * 0.25 * shade);
  vec3 gr = hash33(vec3(floor(p / u_px), 2.0));
  c.x += gr.x * 0.01;
  return outLab(c) * mask + outLab(u_pal[3]) * (1.0 - mask);
}

// Gradient Water: nth's own, its parameters inspired by ruucm/shadergradient (no licence, so its ideas only: a lit water plane seen at an angle deformed by flowing
// noise, coloured by three colours, with grain). Palette: 0 to 2 the three colours, 3 the shadow, 4 the light, 5 the grain tint.
// Options: x = strength (how far the noise moves the surface), y = density (its frequency).
const float T = 36.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float strength = mix(0.15, 1.6, u_opt.x);
  float density = mix(0.6, 3.2, u_opt.y);
  vec2 q = p + tiltD(0.8);
  float persp = 1.0 / max(0.25, 1.15 - q.y * 0.55);
  vec2 uv = vec2(q.x * persp, (q.y + 1.2) * persp * 1.4 + 0.2 * sin(q.x * 3.0 + a * 2.0));
  float shade = 1.0;
  float mask = 1.0;
  float h = fbm3(vec3(uv * density, 0.0) + vec3(cos(a), sin(a), 0.0) * 0.6) * strength;
  float g = sat(0.5 + 0.5 * (uv.y * 0.6 + h));
  vec3 c = mix(u_pal[0], u_pal[1], smoothstep(0.0, 0.55, g));
  c = mix(c, u_pal[2], smoothstep(0.45, 1.0, g));
  float e = 0.02;
  float hx = fbm3(vec3((uv + vec2(e, 0.0)) * density, 0.0) + vec3(cos(a), sin(a), 0.0) * 0.6) * strength - h;
  float hy = fbm3(vec3((uv + vec2(0.0, e)) * density, 0.0) + vec3(cos(a), sin(a), 0.0) * 0.6) * strength - h;
  vec3 nrm = normalize(vec3(-hx / e * 0.15, -hy / e * 0.15, 1.0));
  float lit = sat(dot(nrm, normalize(vec3(-0.4, 0.6, 0.7))));
  c.x += (lit - 0.6) * 0.18 * shade;
  c = mix(c, u_pal[4], pow(lit, 24.0) * 0.25 * shade);
  vec3 gr = hash33(vec3(floor(p / u_px), 2.0));
  c.x += gr.x * 0.01;
  return outLab(c) * mask + outLab(u_pal[3]) * (1.0 - mask);
}

// Gradient Sphere: nth's own, its parameters inspired by ruucm/shadergradient (no licence, so its ideas only: a lit sphere deformed by flowing
// noise, coloured by three colours, with grain). Palette: 0 to 2 the three colours, 3 the shadow, 4 the light, 5 the grain tint.
// Options: x = strength (how far the noise moves the surface), y = density (its frequency).
const float T = 36.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float strength = mix(0.15, 1.6, u_opt.x);
  float density = mix(0.6, 3.2, u_opt.y);
  vec2 q = p + tiltD(0.8);
  float r = length(q) / 0.82;
  float mask = smoothstep(1.0 + u_px * 3.0, 1.0 - u_px * 3.0, r);
  float z = sqrt(sat(1.0 - r * r));
  vec2 uv = q / max(0.35, z + 0.35) * 0.8 + vec2(0.25 * sin(a), 0.0);
  float shade = 0.5 + 0.8 * z;
  float h = fbm3(vec3(uv * density, 0.0) + vec3(cos(a), sin(a), 0.0) * 0.6) * strength;
  float g = sat(0.5 + 0.5 * (uv.y * 0.6 + h));
  vec3 c = mix(u_pal[0], u_pal[1], smoothstep(0.0, 0.55, g));
  c = mix(c, u_pal[2], smoothstep(0.45, 1.0, g));
  float e = 0.02;
  float hx = fbm3(vec3((uv + vec2(e, 0.0)) * density, 0.0) + vec3(cos(a), sin(a), 0.0) * 0.6) * strength - h;
  float hy = fbm3(vec3((uv + vec2(0.0, e)) * density, 0.0) + vec3(cos(a), sin(a), 0.0) * 0.6) * strength - h;
  vec3 nrm = normalize(vec3(-hx / e * 0.15, -hy / e * 0.15, 1.0));
  float lit = sat(dot(nrm, normalize(vec3(-0.4, 0.6, 0.7))));
  c.x += (lit - 0.6) * 0.18 * shade;
  c = mix(c, u_pal[4], pow(lit, 24.0) * 0.25 * shade);
  vec3 gr = hash33(vec3(floor(p / u_px), 2.0));
  c.x += gr.x * 0.01;
  return outLab(c) * mask + outLab(u_pal[3]) * (1.0 - mask);
}

// Plasma: after shader-effects-inc/shaders' Plasma (MIT, THIRD_PARTY_NOTICES "shader-effects-inc shaders"): domain-warped noise on a slab of
// volume, tone-shaped (a glow, a contrast and a balance) and ramped through two colours, here the pack.
// Palette: 0 the dark end, 1 to 4 the ramp, 5 the glow.
// Options: x = warp (how much the flow swirls), y = density.
const float T = 50.0;

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  float warp = mix(0.0, 1.0, u_opt.x);
  float density = mix(0.8, 3.6, u_opt.y);
  vec3 q = vec3(p * density * 0.5 + tiltD(0.5), 0.0);
  vec3 loop = vec3(cos(a), sin(a), 0.0) * 0.5;
  vec3 w = vec3(fbm3(q + loop), fbm3(q + vec3(5.2, 1.3, 0.0) - loop), 0.0);
  float n = fbm3(q + w * 4.0 * warp + loop * 0.5);
  float v = sat(0.5 + 0.5 * n);
  v = sat((v - 0.5) * 1.6 + 0.5);
  v = 1.0 - v;
  vec3 c = mix(u_pal[0], u_pal[1], smoothstep(0.0, 0.3, v));
  c = mix(c, u_pal[2], smoothstep(0.25, 0.55, v));
  c = mix(c, u_pal[3], smoothstep(0.5, 0.8, v));
  c = mix(c, u_pal[4], smoothstep(0.75, 1.0, v));
  c.x += 0.08 * pow(v, 4.0) * mix(0.6, 1.0, u_dark);
  c = mix(c, u_pal[5], 0.15 * pow(v, 6.0));
  return outLab(c);
}

// Gradient: nth's own drawing of ruucm/shadergradient's options (no licence, so its option set and defaults only): a plane, a sphere or a water
// plane, lifted and folded by flowing noise and waves, coloured by three colours, lit by a 3D light or an environment, mirrored by its reflection,
// seen through an orbiting camera (azimuth, polar angle, distance, zoom, field of view), placed and turned by its position and rotation, with grain
// and a wireframe. Every option is a uniform the host fills from the Gradient settings (u_g); the flow travels round a closed loop in noise space,
// so the picture repeats exactly every T seconds (speed is how far round the loop it travels, animate off stills it, a range keeps it between
// its start and end).
// Options (the library card's two): x = motion (how far round the loop the flow travels, times the speed), y = depth (times the lift).
// u_g[0]: shape (0 plane, 1 sphere, 2 water), speed (0 when not animated), strength, density
// u_g[1]: frequency, amplitude, brightness, reflection
// u_g[2]: grain amount (0 off), lighting (0 3D light, 1 environment), environment (0 city, 1 dawn, 2 lobby), wireframe
// u_g[3]: camera azimuth, polar angle (radians), distance, zoom
// u_g[4]: position x, y, z, field of view (radians)
// u_g[5]: rotation x, y, z (radians), range on
// u_g[6], u_g[7], u_g[8]: colour 1, 2, 3 (linear rgb), then range start, range end (seconds), 0
const float T = 40.0;

vec3 rotX(vec3 p, float a) { float c = cos(a); float s = sin(a); return vec3(p.x, c * p.y - s * p.z, s * p.y + c * p.z); }
vec3 rotY(vec3 p, float a) { float c = cos(a); float s = sin(a); return vec3(c * p.x + s * p.z, p.y, -s * p.x + c * p.z); }
vec3 rotZ(vec3 p, float a) { float c = cos(a); float s = sin(a); return vec3(c * p.x - s * p.y, s * p.x + c * p.y, p.z); }
// world to the surface's own space: the position taken off, then the rotation undone (Z, then Y, then X: the inverse of X, Y, Z)
vec3 toLocal(vec3 p) { return rotX(rotY(rotZ(p, -u_g[5].z), -u_g[5].y), -u_g[5].x); }
vec3 toWorldDir(vec3 d) { return rotZ(rotY(rotX(d, u_g[5].x), u_g[5].y), u_g[5].z); }

// the lift at a point of the surface's own 2D coordinates, at flow angle a
float lift(vec2 q, float a) {
  float r = u_g[0].y * 0.9 * mix(0.5, 1.5, u_opt.x);
  float n = gnoise(loop3(q * u_g[0].w * 0.45, a, r) + vec3(0.0, 0.0, 3.7));
  float w = sin(q.x * u_g[1].x * 0.35 + r * 2.0 * sin(a) + n * 1.5) * u_g[1].y * 0.06;
  return (n * u_g[0].z * 0.09 + w) * mix(0.5, 1.5, u_opt.y);
}

vec3 envColour(vec3 n) {
  float e = u_g[2].z;
  vec3 skyC = e < 0.5 ? vec3(0.55, 0.62, 0.72) : (e < 1.5 ? vec3(0.95, 0.62, 0.42) : vec3(0.92, 0.90, 0.86));
  vec3 groundC = e < 0.5 ? vec3(0.16, 0.17, 0.20) : (e < 1.5 ? vec3(0.28, 0.16, 0.18) : vec3(0.42, 0.38, 0.34));
  return mix(groundC, skyC, sat(0.5 + 0.5 * n.y));
}

vec3 wall(vec2 p, float t) {
  float a = TAU * t / T;
  // a range: the flow swings between its start and end and back once a loop
  if (u_g[5].w > 0.5) a = TAU * (u_g[6].w + (u_g[7].w - u_g[6].w) * (0.5 - 0.5 * cos(a))) / T;
  vec3 c1 = u_g[6].xyz; vec3 c2 = u_g[7].xyz; vec3 c3 = u_g[8].xyz;
  // the camera: orbiting the origin, looking at it
  float az = u_g[3].x; float po = clamp(u_g[3].y, 0.02, 3.12); float dist = u_g[3].z;
  vec3 ro = dist * vec3(sin(po) * sin(az), cos(po), sin(po) * cos(az));
  vec3 fw = normalize(-ro);
  vec3 rt = normalize(cross(fw, vec3(0.0, 1.0, 0.0)));
  vec3 up = cross(rt, fw);
  float focal = 1.0 / tan(0.5 * u_g[4].w) * u_g[3].w;
  vec2 q = p + tiltD(0.6);
  vec3 rd = normalize(fw * focal + rt * q.x + up * q.y);
  // into the surface's own space
  vec3 lo = toLocal(ro - u_g[4].xyz);
  vec3 ld = toLocal(rd);
  float shape = u_g[0].x;
  bool hit = false;
  vec3 hp = vec3(0.0);
  vec3 nrm = vec3(0.0, 0.0, 1.0);
  vec2 uv = vec2(0.0);
  if (shape < 0.5 || shape > 1.5) {
    // a plane (z = 0; the water plane lies flat, y = 0, and rolls with longer waves) lifted along its normal: the ray's height test, refined
    vec3 o = lo; vec3 d = ld;
    if (shape > 1.5) { o = vec3(lo.x, lo.z, lo.y); d = vec3(ld.x, ld.z, ld.y); }
    if (abs(d.z) > 0.0005) {
      float tt = -o.z / d.z;
      for (int i = 0; i < 5; i++) {
        vec3 s = o + d * tt;
        float h = lift(s.xy * (shape > 1.5 ? 0.6 : 1.0), a);
        tt = (h - o.z) / d.z;
      }
      vec3 s = o + d * tt;
      if (tt > 0.0 && abs(s.x) < 5.0 && abs(s.y) < 5.0) {
        hit = true;
        float k = shape > 1.5 ? 0.6 : 1.0;
        float e = 0.02;
        float h0 = lift(s.xy * k, a);
        float hx = lift((s.xy + vec2(e, 0.0)) * k, a) - h0;
        float hy = lift((s.xy + vec2(0.0, e)) * k, a) - h0;
        vec3 n = normalize(vec3(-hx / e, -hy / e, 1.0));
        if (dot(n, d) > 0.0) n = -n;
        nrm = shape > 1.5 ? vec3(n.x, n.z, n.y) : n;
        uv = s.xy * 0.1 + 0.5;
        hp = s;
      }
    }
  } else {
    // a sphere of radius 1 lifted along its radius
    float r = 1.0;
    for (int i = 0; i < 4; i++) {
      float b = dot(lo, ld); float c = dot(lo, lo) - r * r; float disc = b * b - c;
      if (disc < 0.0) { r = -1.0; break; }
      vec3 s = lo + ld * (-b - sqrt(disc));
      vec3 sn = normalize(s);
      r = 1.0 + lift(vec2(atan(sn.z, sn.x) * 1.6, sn.y * 2.6), a);
    }
    if (r > 0.0) {
      float b = dot(lo, ld); float c = dot(lo, lo) - r * r; float disc = b * b - c;
      if (disc >= 0.0) {
        hit = true;
        vec3 s = lo + ld * (-b - sqrt(disc));
        vec3 sn = normalize(s);
        vec2 sq = vec2(atan(sn.z, sn.x) * 1.6, sn.y * 2.6);
        float e = 0.02;
        float h0 = lift(sq, a);
        float hx = lift(sq + vec2(e, 0.0), a) - h0;
        float hy = lift(sq + vec2(0.0, e), a) - h0;
        nrm = normalize(sn - 0.6 * (hx / e) * normalize(cross(vec3(0.0, 1.0, 0.0), sn) + vec3(1e-4)) - 0.6 * (hy / e) * vec3(0.0, 1.0, 0.0));
        uv = vec2(sq.x * 0.1 + 0.5, sn.y * 0.5 + 0.5);
        hp = s;
      }
    }
  }
  vec3 col;
  if (!hit) {
    // past the surface: a quiet field of its colours
    col = mix(c3, c2, sat(0.5 + 0.5 * p.y)) * 0.35;
  } else {
    float h = lift(hp.xy, a);
    float g = sat(0.5 + h * 2.2 + (uv.y - 0.5) * 0.8);
    col = mix(c1, c2, smoothstep(0.0, 0.55, g));
    col = mix(col, c3, smoothstep(0.45, 1.0, g));
    vec3 n = toWorldDir(nrm);
    vec3 v = -rd;
    vec3 light;
    if (u_g[2].y < 0.5) {
      vec3 l = normalize(vec3(-0.4, 0.7, -0.6));
      float diff = sat(dot(n, l));
      float spec = pow(sat(dot(reflect(-l, n), v)), 24.0);
      light = col * (0.35 + 0.75 * diff) + vec3(spec) * 0.35;
    } else {
      light = col * envColour(n) * 1.25;
    }
    float fres = pow(1.0 - sat(abs(dot(n, v))), 3.0);
    light = mix(light, envColour(reflect(-v, n)), sat(u_g[1].w * (0.25 + 0.75 * fres)));
    col = light * u_g[1].z;
    // the wireframe: the surface's grid lines
    if (u_g[2].w > 0.5) {
      vec2 gl = abs(fract(uv * 24.0) - 0.5);
      float line = 1.0 - smoothstep(0.0, 0.06, min(gl.x, gl.y));
      col = mix(col * 0.15, col * 1.3, line);
    }
  }
  // film grain, still from frame to frame so the loop holds
  vec3 gr = hash33(vec3(floor(p / u_px), 9.0));
  col += vec3(gr.x * 0.12 * u_g[2].x);
  return lin2srgb(shoulder(max(col, vec3(0.0))));
}

// shader-effects-inc/shaders (MIT, THIRD_PARTY_NOTICES "shader-effects-inc shaders"), ported by nth from each effect's emitted WGSL (the
// package's own shader snapshots) into the wallpaper library's GLSL subset. Shared by every effect of the Shaders section:
// - its options are the effect's own props, in u_e (the host fills them from the Shaders settings: colours as linear rgba, numbers as given);
// - the package's integer (bit-op) Perlin hash cannot run on the subset (no bit operations), so its Perlin noise is the library's gradient noise;
// - its time runs on, so the loop is closed by crossfading the effect at t with itself at t - T across the loop (frame T is frame 0 exactly).
const float T = 60.0;
vec2 sUV(vec2 p) { float a = u_res.x / max(u_res.y, 1.0); return vec2((p.x / a + 1.0) * 0.5, (p.y + 1.0) * 0.5); }
